*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#eef2ff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.wrap{max-width:1450px;margin:auto;padding:32px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.brand{display:flex;align-items:center;gap:14px}.brand-logo{width:54px;height:54px;object-fit:contain;border-radius:12px;background:#fff;padding:5px}.brand-name{font-size:13px;font-weight:800;color:#e2e8f0}.title{font-size:30px;font-weight:800;margin:4px 0}.actions{display:flex;gap:10px;align-items:center}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;padding:11px 16px;background:#1e293b;color:#fff;cursor:pointer;font-weight:700;text-decoration:none}.btn.primary{background:#2563eb}.btn.danger{background:#7f1d1d}.btn.logout{background:#334155}.card{background:#111827;border:1px solid #1f2937;border-radius:18px;padding:22px;box-shadow:0 18px 50px #0003}.project-list-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 18px}.project-list-head h2{font-size:18px;margin:0}.project-count{font-size:12px;font-weight:800;color:#93c5fd;background:#172554;border:1px solid #2b4b83;border-radius:999px;padding:6px 11px;white-space:nowrap}.project-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.project{position:relative;border:1px solid #263246;background:#0d1424;border-radius:14px;padding:17px 17px 17px 58px;margin:0;cursor:grab;transition:.18s}.project:active{cursor:grabbing}.project.dragging{opacity:.45;transform:scale(.99)}.project.drag-over{border-color:#38bdf8;box-shadow:0 0 0 2px #38bdf822}.project-number{position:absolute;left:16px;top:17px;width:30px;height:30px;border-radius:9px;background:#172554;color:#93c5fd;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900}.project-head{display:flex;justify-content:space-between;gap:12px}.project-name{font-weight:800;font-size:16px}.badge{font-size:11px;border-radius:999px;padding:5px 9px;background:#172554;color:#93c5fd;white-space:nowrap;cursor:pointer;border:1px solid #2b4b83;transition:.15s}.badge:hover{background:#1d4ed8;color:#fff;transform:translateY(-1px)}.meta{font-size:12px;color:#94a3b8;margin-top:5px}.progress-summary{margin-top:14px}.progress-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.progress-label{font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-weight:800}.progress-value{font-size:16px;font-weight:850;color:#7dd3fc}.progress-bar{height:7px;border-radius:99px;background:#1e293b;overflow:hidden}.progress-fill{height:100%;border-radius:99px;background:#38bdf8}.project-actions{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-top:13px}.project-actions form{margin:0}.action-icon{width:40px;height:40px;padding:0;border-radius:10px;font-size:18px;line-height:1}.action-icon svg{width:18px;height:18px;display:block}.drag-handle{float:right;color:#64748b;font-size:18px;line-height:1;margin-left:8px;user-select:none}.empty{padding:40px;text-align:center;color:#64748b}.order-status{font-size:11px;color:#64748b;margin:-10px 0 14px}.modal-backdrop{position:fixed;inset:0;background:#020617b8;backdrop-filter:blur(7px);display:none;align-items:center;justify-content:center;padding:20px;z-index:1000}.modal-backdrop.open{display:flex}.progress-modal{width:min(520px,100%);background:linear-gradient(145deg,#121a2b,#0d1423);border:1px solid #2b3a52;border-radius:22px;box-shadow:0 30px 90px #0008;padding:26px}.modal-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:24px}.modal-eyebrow{font-size:11px;color:#7dd3fc;font-weight:850;text-transform:uppercase;letter-spacing:.1em}.modal-title{font-size:22px;font-weight:850;margin-top:5px}.modal-client{font-size:12px;color:#64748b;margin-top:4px}.modal-close{width:38px;height:38px;border:1px solid #2b3a52;border-radius:10px;background:#172033;color:#cbd5e1;font-size:20px;cursor:pointer}.modal-close:hover{background:#1e293b;color:#fff}.modal-progress-box{background:#0a1120;border:1px solid #2b3a52;border-radius:16px;padding:20px}.modal-progress-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal-progress-label{font-size:12px;color:#cbd5e1;font-weight:850;text-transform:uppercase;letter-spacing:.08em}.modal-progress-value{font-size:30px;font-weight:900;color:#7dd3fc}.modal-slider{width:100%;height:10px;appearance:none;-webkit-appearance:none;border-radius:99px;background:linear-gradient(to right,#38bdf8 0%,#38bdf8 var(--progress),#1e293b var(--progress),#1e293b 100%);outline:none;cursor:pointer}.modal-slider::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:23px;height:23px;border-radius:50%;background:#fff;border:3px solid #38bdf8;box-shadow:0 3px 14px #0006}.modal-slider::-moz-range-thumb{width:17px;height:17px;border-radius:50%;background:#fff;border:3px solid #38bdf8}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.saving{opacity:.7;pointer-events:none}@media(max-width:760px){.project-grid{grid-template-columns:1fr}.top{align-items:flex-start;gap:15px;flex-direction:column}.wrap{padding:18px}.project-actions{justify-content:flex-end}.brand-logo{width:46px;height:46px}.modal-actions{flex-direction:column}.modal-actions .btn{width:100%}.actions{width:100%;flex-wrap:wrap}.actions .btn,.actions form{flex:1}.actions form .btn{width:100%}}
</style>
</head>
<body>
