<div class="card"><div class="project-list-head"><h2>Daftar Project</h2><span class="project-count">{{ $projects->count() }} Project</span></div><div class="order-status" id="orderStatus">↕ Drag project untuk mengatur urutan tampil di monitor. Klik progress untuk mengubah progress.</div><div id="projectList" class="project-grid">
@forelse($projects as $project)
