</div></div></div>

<div class="modal-backdrop" id="progressModal" aria-hidden="true"><div class="progress-modal" role="dialog" aria-modal="true" aria-labelledby="progressModalTitle"><div class="modal-head"><div><div class="modal-eyebrow">Update Progress</div><div class="modal-title" id="progressModalTitle">Project</div><div class="modal-client" id="progressModalClient">Client</div></div><button type="button" class="modal-close" id="progressClose" aria-label="Tutup">×</button></div><div class="modal-progress-box"><div class="modal-progress-head"><span class="modal-progress-label">Project Progress</span><span class="modal-progress-value" id="modalProgressValue">0%</span></div><input class="modal-slider" id="modalProgressSlider" type="range" min="0" max="100" step="1" value="0" style="--progress:0%"></div><div class="modal-actions"><button type="button" class="btn" id="progressCancel">Batal</button><button type="button" class="btn primary" id="progressSave">Simpan Progress →</button></div></div></div>

<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const csrf='{{ csrf_token() }}';
document.querySelectorAll('.delete-form').forEach(form=>form.addEventListener('submit',function(e){e.preventDefault();Swal.fire({title:'Hapus project?',text:'Project ini akan dihapus permanen.',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal',confirmButtonColor:'#dc2626'}).then(r=>{if(r.isConfirmed)this.submit()})}));
@if(session('success'))Swal.fire({toast:true,position:'top-end',icon:'success',title:@json(session('success')),showConfirmButton:false,timer:2200,timerProgressBar:true});@endif
const modal=document.getElementById('progressModal'),slider=document.getElementById('modalProgressSlider'),value=document.getElementById('modalProgressValue'),title=document.getElementById('progressModalTitle'),client=document.getElementById('progressModalClient');let activeId=null;
function syncProgress(){value.textContent=slider.value+'%';slider.style.setProperty('--progress',slider.value+'%')}
function openProgress(trigger){activeId=trigger.dataset.id;title.textContent=trigger.dataset.name;client.textContent=trigger.dataset.client;slider.value=trigger.dataset.progress;syncProgress();modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>slider.focus(),50)}
function closeProgress(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');activeId=null}
document.querySelectorAll('.progress-trigger').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();openProgress(el)}));slider.addEventListener('input',syncProgress);document.getElementById('progressClose').addEventListener('click',closeProgress);document.getElementById('progressCancel').addEventListener('click',closeProgress);modal.addEventListener('click',e=>{if(e.target===modal)closeProgress()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeProgress()});
document.getElementById('progressSave').addEventListener('click',async()=>{if(!activeId)return;const button=document.getElementById('progressSave');button.classList.add('saving');button.textContent='Menyimpan...';try{const response=await fetch(`{{ url('/admin/projects') }}/${activeId}/progress`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({progress:Number(slider.value)})});const data=await response.json();if(!response.ok||!data.success)throw new Error('Gagal menyimpan');closeProgress();Swal.fire({toast:true,position:'top-end',icon:'success',title:'Progress diperbarui',showConfirmButton:false,timer:1500});setTimeout(()=>location.reload(),350)}catch(error){Swal.fire({icon:'error',title:'Gagal menyimpan',text:'Progress belum berhasil diperbarui.'})}finally{button.classList.remove('saving');button.textContent='Simpan Progress →'}});
const list=document.getElementById('projectList');let dragged=null;list?.querySelectorAll('.project').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',()=>{card.classList.remove('dragging');updateNumbers();saveOrder()});card.addEventListener('dragover',e=>{e.preventDefault();if(card!==dragged){const rect=card.getBoundingClientRect();const after=e.clientY>rect.top+rect.height/2;if(after)card.after(dragged);else card.before(dragged)}})});function updateNumbers(){list?.querySelectorAll('.project-number').forEach((number,index)=>number.textContent=index+1)}function saveOrder(){const ids=[...list.querySelectorAll('.project')].map(x=>x.dataset.id);fetch('{{ route('admin.projects.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({ids})}).then(r=>r.json()).then(d=>{if(d.success)Swal.fire({toast:true,position:'top-end',icon:'success',title:'Urutan tersimpan',showConfirmButton:false,timer:1200})})}
</script>
</body></html>
